import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.em2JOrjF.js";const u=JSON.parse('{"title":"Retainers","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/retainers.md","filePath":"concepts/retainers.md"}'),n={name:"concepts/retainers.md"};function s(i,e,l,d,h,c){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="retainers" tabindex="-1">Retainers <a class="header-anchor" href="#retainers" aria-label="Permalink to &quot;Retainers&quot;">​</a></h1><p>Retainers are ongoing client relationships billed at a fixed monthly fee for a set number of hours. VERA&#39;s job with retainers is to keep you honest on pace — not just over-spending, but under-delivering too.</p><hr><h2 id="how-retainers-work" tabindex="-1">How retainers work <a class="header-anchor" href="#how-retainers-work" aria-label="Permalink to &quot;How retainers work&quot;">​</a></h2><p>A retainer project has a <code>budget_hours</code> value that represents the annual hours committed to the client (e.g. 480 h/yr = 40 h/month).</p><p>Unlike Fixed Price or T&amp;M, retainer revenue is not calculated per entry. The client pays a monthly fee regardless of exact hours logged. What matters is whether the agency is delivering what was promised.</p><p><strong>Underspend is as problematic as overspend.</strong> If the agency logs 20 of a 40-hour monthly budget, the client paid for 40 hours of value and received 20. That&#39;s a relationship problem. VERA flags both directions.</p><hr><h2 id="burn-rate" tabindex="-1">Burn rate <a class="header-anchor" href="#burn-rate" aria-label="Permalink to &quot;Burn rate {#burn-rate}&quot;">​</a></h2><p>Burn rate is the pace at which a retainer is consuming its monthly budget.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pace_per_day = hours_logged ÷ days_elapsed</span></span>
<span class="line"><span>projected_eom_hours = pace_per_day × days_in_month</span></span></code></pre></div><p>VERA compares the projected end-of-month total against the monthly budget and categorises it:</p><table tabindex="0"><thead><tr><th>Status</th><th>Projected utilisation</th><th>What it means</th></tr></thead><tbody><tr><td>🚨 Critical overpace</td><td>&gt; 150%</td><td>You&#39;ll burn 3× the budget at this rate</td></tr><tr><td>⚠️ Warning overpace</td><td>110–150%</td><td>Trending 20–50% over budget</td></tr><tr><td>✅ On track</td><td>90–110%</td><td>Right on target</td></tr><tr><td>⚠️ Warning underpace</td><td>50–90%</td><td>Using less than planned — may underdeliver</td></tr><tr><td>🚨 Critical underpace</td><td>&lt; 50%</td><td>Leaving major value unused — client paid for work not delivered</td></tr></tbody></table><hr><h2 id="allocation-aware-forecast" tabindex="-1">Allocation-aware forecast <a class="header-anchor" href="#allocation-aware-forecast" aria-label="Permalink to &quot;Allocation-aware forecast {#allocation-aware-forecast}&quot;">​</a></h2><p>VERA can project retainer hours two ways:</p><p><strong>1. Pace-based</strong> (historical only)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>projected_eom_hours = pace_per_day × days_in_month</span></span></code></pre></div><p>Based purely on how fast hours have been accumulating. Accurate if the rest of the month looks like the past.</p><p><strong>2. Allocation-aware</strong> (recommended)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>forecast_with_allocations = hours_logged + allocated_remaining</span></span></code></pre></div><p>Where <code>allocated_remaining</code> is the total of active allocation envelopes for the remaining weeks of the month.</p><p>This is more accurate when Managers actively plan work via allocations. If your team has 12 hours allocated to a retainer for the rest of the month and has already logged 25 of 40 hours, the allocation-aware forecast shows 37 hours — right on target.</p><p><strong>When to prefer each:</strong></p><ul><li>Use allocation-aware when Managers consistently maintain allocations</li><li>Use pace-based when allocations are sparse or rarely updated</li></ul><hr><h2 id="retainer-workflow" tabindex="-1">Retainer workflow <a class="header-anchor" href="#retainer-workflow" aria-label="Permalink to &quot;Retainer workflow&quot;">​</a></h2><p>When asked about a retainer&#39;s status, VERA always follows this sequence:</p><ol><li><code>get_project_info</code> — verify the project type is Retainer</li><li><code>get_retainer_status</code> — fetch current month burn rate, pace, forecast, and unused value</li></ol><p>This is mandatory. Never use <code>get_project_status</code> (task budgets) for retainers — it&#39;s misleading because retainers are governed by monthly burn rate, not task-level caps.</p><hr><h2 id="what-vera-shows-in-a-retainer-summary" tabindex="-1">What VERA shows in a retainer summary <a class="header-anchor" href="#what-vera-shows-in-a-retainer-summary" aria-label="Permalink to &quot;What VERA shows in a retainer summary&quot;">​</a></h2><p>When you ask &quot;how is Nike tracking this month?&quot;:</p><ul><li><strong>Hours logged</strong> vs. monthly budget</li><li><strong>Days elapsed</strong> in the current month</li><li><strong>Projected end-of-month</strong> total (pace-based)</li><li><strong>Forecast with allocations</strong> (if allocations exist)</li><li><strong>When budget will be exceeded</strong> (if overpace)</li><li><strong>Unused dollar value</strong> (if underpace): <code>unused_hours × billing_rate</code></li><li><strong>Status</strong> with urgency emoji</li></ul><hr><h2 id="retainer-budget-field" tabindex="-1">Retainer budget field <a class="header-anchor" href="#retainer-budget-field" aria-label="Permalink to &quot;Retainer budget field&quot;">​</a></h2><p>The <code>budget_hours</code> field on a Retainer project stores the <strong>annual</strong> total (e.g. 480 for 40/month). VERA divides by 12 internally to get the monthly cap for burn rate calculations.</p><hr><h2 id="morning-summary-managers-owners" tabindex="-1">Morning summary (Managers/Owners) <a class="header-anchor" href="#morning-summary-managers-owners" aria-label="Permalink to &quot;Morning summary (Managers/Owners)&quot;">​</a></h2><p>The morning reminder includes retainer status for all assigned retainers. Critical and warning items are surfaced automatically — you don&#39;t need to ask.</p><hr><h2 id="multiple-retainers" tabindex="-1">Multiple retainers <a class="header-anchor" href="#multiple-retainers" aria-label="Permalink to &quot;Multiple retainers&quot;">​</a></h2><p><code>get_pm_retainer_summary</code> gives a Manager a rolled-up view of all their retainer projects — status, pace, and utilisation for each. Use this for a quick portfolio check without drilling into each project individually.</p>`,43)])])}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
